"use strict";(globalThis.webpackChunkdocs_workspace=globalThis.webpackChunkdocs_workspace||[]).push([[9369],{94351(n,e,t){t.r(e),t.d(e,{assets:()=>c,contentTitle:()=>s,default:()=>d,frontMatter:()=>a,metadata:()=>r,toc:()=>l});const r=JSON.parse('{"id":"basic/09","title":"\u900f\u660e\u53ca\u78e8\u7802\u80cc\u666f","description":"lencx","source":"@site/content/tauri/docs/basic/09.md","sourceDirName":"basic","slug":"/basic/09","permalink":"/tauri-doc/docs/basic/09","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{},"sidebar":"tutorialSidebar","previous":{"title":"\u57fa\u672c\u914d\u7f6e","permalink":"/tauri-doc/docs/basic/08"},"next":{"title":"\u7cfb\u7edf\u6587\u4ef6","permalink":"/tauri-doc/docs/basic/10"}}');var o=t(74848),i=t(28453);const a={},s="\u900f\u660e\u53ca\u78e8\u7802\u80cc\u666f",c={},l=[];function u(n){const e={code:"code",h1:"h1",header:"header",p:"p",pre:"pre",...(0,i.R)(),...n.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(e.header,{children:(0,o.jsx)(e.h1,{id:"\u900f\u660e\u53ca\u78e8\u7802\u80cc\u666f",children:"\u900f\u660e\u53ca\u78e8\u7802\u80cc\u666f"})}),"\n",(0,o.jsx)(e.p,{children:"lencx"}),"\n",(0,o.jsx)(e.pre,{children:(0,o.jsx)(e.code,{children:'{\u6298\u817e \u21cc \u8ff7\u832b \u21cc \u601d\u8003]ing\uff0c\u5728\u8def\u4e0a...\n\u200b\u5173\u6ce8\u4ed6\n39 \u4eba\u8d5e\u540c\u4e86\u8be5\u6587\u7ae0\n\u4ed3\u5e93\uff1alencx/OhMyBox\n\u9605\u8bfb\u539f\u6587\uff08\u9996\u53d1\u4e8e GitHub\uff09\n\u5173\u6ce8\u300a\u6d6e\u4e4b\u9759\u300b\u516c\u4f17\u53f7\uff0c\u79c1\u4fe1\u4f5c\u8005\uff0c\u8fdb Tauri \u6280\u672f\u4ea4\u6d41\u7fa4\n\u4ece\u6b64\u7bc7\u5f00\u59cb\uff0c\u6587\u7ae0\u5c06\u8fdb\u5165\u5b9e\u6218\u73af\u8282\uff0c\u91cc\u9762\u4f1a\u5305\u542b\u5927\u91cf\u7684\u4e2a\u4eba\u63a2\u7d22\u5b66\u4e60\u3002\u65e0\u6cd5\u4fdd\u8bc1\u5176\u662f\u5426\u4e3a\u6700\u4f73\u5b9e\u8df5\uff0c\u4f46\u662f\u6211\u4f1a\u5c3d\u91cf\u5ba2\u89c2\u5730\u5c06\u76f8\u5173\u8d44\u6599\u53ca\u5b66\u4e60\u8fc7\u7a0b\u8bb0\u5f55\u4e0b\u6765\u3002\u867d\u7136Tauri\u5df2\u7ecf\u53d1\u5e03v1.0\u7248\u672c\uff0c\u4f46\u662f\u5230\u76ee\u524d\u4e3a\u6b62\uff0c\u56fd\u5185\u8d44\u6599\u5c11\u7684\u53ef\u601c\uff0c\u6211\u4e2a\u4eba\u60f3\u57fa\u4e8eTauri\u5f00\u53d1\u4e00\u6b3e\u5de5\u5177\u96c6\uff08\u5404\u79cd\u5c0f\u529f\u80fd\uff09\u3002\u5728\u8fd9\u4e2a\u8fc7\u7a0b\u4e2d\uff0c\u6211\u9047\u5230\u4e86\u4e00\u4e9b\uff0c\u6216\u8005\u8bf4\u662f\u4e00\u7cfb\u5217\u7684\u95ee\u9898\uff0c\u6211\u5c31\u60f3\u628a\u5b83\u4eec\u4ee5\u4e13\u680f\u7cfb\u5217\u7684\u5f62\u5f0f\u8bb0\u5f55\u4e0b\u6765\uff08\u597d\u8bb0\u6027\u4e0d\u5982\u70c2\u7b14\u5934\uff09\uff0c\u5e0c\u671b\u53ef\u4ee5\u5e2e\u52a9\u5230\u66f4\u591a\u548c\u6211\u4e00\u6837\u5bf9\u65b0\u6280\u672f\u5145\u6ee1\u70ed\u60c5\u7684\u4eba\u3002 \u5982\u679c\u8fd9\u4e9b\u6587\u7ae0\u5bf9\u4f60\u6709\u6240\u5e2e\u52a9\uff0c\u53ef\u4ee5 star \u6b64\u9879\u76ee \u6216\u8005\u5c06\u6587\u7ae0\u8f6c\u53d1\u7ed9\u66f4\u591a\u6709\u9700\u8981\u7684\u4eba\u3002\u5927\u5bb6\u7684\u652f\u6301\u4e5f\u4f1a\u7ed9\u6211\u66f4\u5927\u7684\u5199\u4f5c\u52a8\u529b\uff0c\u611f\u6069\u3002\n\n\u6e90\u7801\u9605\u8bfb\n\u5b98\u65b9\u6587\u6863\u662f\u7b2c\u4e00\u624b\u5b66\u4e60\u8d44\u6599\uff0c\u5f53\u6587\u6863\u4e0d\u80fd\u6ee1\u8db3\u9700\u8981\u65f6\uff0c\u4e86\u89e3\u5176\u751f\u6001\uff0c\u6216\u8005\u9605\u8bfb\u4e00\u4e9b\u6e90\u7801\uff0c\u53ef\u80fd\u4f1a\u6709\u610f\u60f3\u4e0d\u5230\u7684\u6536\u83b7\u3002\n\u901a\u8fc7\u9605\u8bfb wry \u6e90\u7801\u793a\u4f8b \u53ef\u77e5 Tauri \u5e94\u7528\u7684\u80cc\u666f\u5206\u4e09\u5c42\uff1a\n\n\u7b2c\u4e00\u5c42\u662f window\n\u7b2c\u4e8c\u5c42\u662f webview\n\u7b2c\u4e09\u5c42\u662f html\nfn main() -> wry::Result<()> {\n  use wry::{\n    application::{\n      event::{Event, WindowEvent},\n      event_loop::{ControlFlow, EventLoop},\n      window::WindowBuilder,\n    },\n    webview::WebViewBuilder,\n  };\n\n  let event_loop = EventLoop::new();\n  let window = WindowBuilder::new()\n    .with_decorations(false)\n    // \u2705 \u7b2c\u4e00\u5c42\uff1a\n    // There are actually three layer of background color when creating webview window.\n    // The first is window background...\n    .with_transparent(true)\n    .build(&event_loop)\n    .unwrap();\n\n  let _webview = WebViewBuilder::new(window)?\n    // \u2705 \u7b2c\u4e8c\u5c42\uff1a\n    // The second is on webview...\n    .with_transparent(true)\n    // \u2705 \u7b2c\u4e09\u5c42\uff1a\n    // And the last is in html.\n    .with_url(\n      r#"data:text/html,\n            <!doctype html>\n            <html>\n              <body style="background-color:rgba(87,87,87,0.5);">hello</body>\n              <script>\n                window.onload = function() {\n                  document.body.innerText = `hello, ${navigator.userAgent}`;\n                };\n              <\/script>\n            </html>"#,\n    )?\n    .build()?;\n\n  event_loop.run(move |event, _, control_flow| {\n    *control_flow = ControlFlow::Wait;\n\n    match event {\n      Event::WindowEvent {\n        event: WindowEvent::CloseRequested,\n        ..\n      } => *control_flow = ControlFlow::Exit,\n      _ => {}\n    }\n  });\n}\n\u6240\u4ee5\u5982\u679c\u6211\u4eec\u60f3\u8981\u5b9e\u73b0\u78e8\u7802\u6216\u534a\u900f\u660e\u5e94\u7528\u5e94\u8be5\u4ece\u8fd9\u4e09\u65b9\u9762\u7684\u914d\u7f6e\u5165\u624b\u3002\n\n\u900f\u660e\u80cc\u666f\ntauri.conf.json \u914d\u7f6e\n\u5728\u5b98\u65b9\u6587\u6863 tauri.conf.json \u7a97\u53e3\u914d\u7f6e\u4e2d\u6709 transparent \u5b57\u6bb5\uff0c\u8bbe\u7f6e\u4e3a true \u542f\u7528\u900f\u660e\u5ea6\u3002\uff08\u9ed8\u8ba4\u4e3a false\uff0c\u4e0d\u542f\u7528\uff09\n\n\u6ce8\u610f\uff1a\u5728 macOS \u4e0a\uff0c\u9700\u8981\u4ece tauri.conf.json > tauri > macOSPrivateApi \u542f\u7528 macos-private-api \uff0c\u9ed8\u8ba4\u4e3a false\uff0c\u4e0d\u542f\u7528\u3002\uff08\u8b66\u544a\uff1a\u5728 macOS \u4e0a\u4f7f\u7528\u79c1\u6709 API \u7684\u5e94\u7528\u7a0b\u5e8f\u4f1a\u88ab App Store \u62d2\u7edd\uff09\n\nmacOSPrivateApi \u8bbe\u7f6e\u4e3a true \u65f6\uff1a\n\n\u542f\u7528\u900f\u660e\u80cc\u666f API\n\u5c06 fullScreenEnabled \u9996\u9009\u9879\u8bbe\u7f6e\u4e3a true\n{\n  "tauri": {\n    "macOSPrivateApi": true,\n    "windows": [\n      {\n        "width": 800,\n        "height": 600,\n        "resizable": true,\n        "fullscreen": false,\n        "title": "Oh My Box",\n        "transparent": true\n      }\n    ]\n  }\n}\nhtml \u914d\u7f6e\n\u7a97\u53e3\u914d\u7f6e\u4e2d\u7684 transparent \u662f\u5f00\u542f\u7b2c\u4e00\u5c42\uff08window\uff09\u548c\u7b2c\u4e8c\u5c42\uff08webview\uff09\u7684\u900f\u660e\u5ea6\u3002\u5982\u679c\u900f\u660e\u5ea6\u672a\u751f\u6548\uff0c\u8bf7\u68c0\u67e5 html \u662f\u5426\u8bbe\u7f6e\u4e86\u4e0d\u900f\u660e\u80cc\u666f\u8272\uff0c\u5c06\u5176\u4fee\u6539\u4e3a RGBA \u6216 transparent\u3002\u4e5f\u53ef\u4ee5\u901a\u8fc7 css \u6587\u4ef6\u8bbe\u7f6e body \u6837\u5f0f\u3002\n\n<!DOCTYPE html>\n<html>\n  <body style="background-color: rgba(87,87,87,0.5);">\n    <div id="root"></div>\n  </body>\n</html>\n\u52a8\u56fe\u5c01\u9762\n\u6ce8\u610f\uff1a\u5728 macOS \u4e2d\u4f7f\u7528\u900f\u660e\u80cc\u666f\u5728\u9875\u9762\u8df3\u8f6c\u65f6\u4f1a\u51fa\u73b0\u6b8b\u5f71\uff0c\u6682\u672a\u4e86\u89e3\u5230\u76f8\u5173\u89e3\u51b3\u65b9\u6848\n\n\n\u78e8\u7802\u80cc\u666f\n\u900f\u660e\u80cc\u666f\u867d\u7136\u5f88\u9177\uff0c\u4f46\u5b9e\u7528\u6027\u4f4e\u3002\u56e0\u4e3a\u5728\u4f7f\u7528\u5e94\u7528\u65f6\u5f88\u5bb9\u6613\u53d7\u5230\u684c\u9762\u80cc\u666f\u7684\u5e72\u6270\uff0c\u6240\u4ee5\u78e8\u7802\u80cc\u666f\u66f4\u7b26\u5408\u4f7f\u7528\u573a\u666f\u3002\n\n\u5b98\u7f51\u5e76\u6ca1\u6709\u7ed9\u51fa\u78e8\u7802\u80cc\u666f\u7684\u76f8\u5173\u914d\u7f6e\uff0c\u76f4\u63a5\u5728\u7b2c\u4e09\u5c42 html \u4e2d\u4f7f\u7528 css \u5c5e\u6027\u5b9e\u73b0\u6a21\u7cca\u6548\u679c\u4e5f\u4f1a\u5b58\u5728\u4e00\u4e9b\u95ee\u9898\uff0c\u5177\u4f53\u539f\u56e0\u53ef\u4ee5\u67e5\u770b Blurry and translucent background on a transparent window\uff0cissues \u4e2d\u4f5c\u8005\u63d0\u5230\u53ef\u80fd\u4f1a\u5728 tauri v2 \u7248\u672c\u4e2d\u652f\u6301\u6b64\u529f\u80fd\uff0c\u8fc7\u6e21\u65b9\u6848\u53ef\u4ee5\u4f7f\u7528 tauri-apps/window-vibrancy \u63d2\u4ef6\u3002\u6240\u4ee5\u63a5\u4e0b\u6765\u7684\u914d\u7f6e\u5c06\u56f4\u7ed5 tauri-apps/window-vibrancy \u8fdb\u884c\uff1a\n\nStep 1\n\u5b89\u88c5 window-vibrancy \u4f9d\u8d56\uff0c\u63a8\u8350\u4f7f\u7528 cargo edit\uff08\u8be5\u5de5\u5177\u6269\u5c55\u4e86 Cargo\uff0c\u5141\u8bb8\u4f60\u901a\u8fc7\u4ece\u547d\u4ee4\u884c\u4fee\u6539 Cargo.toml \u6587\u4ef6\u6765\u6dfb\u52a0\u3001\u5220\u9664\u548c\u5347\u7ea7\u4f9d\u8d56\u9879\uff09 \uff1a\n\n# 1. \u547d\u4ee4\u8fdb\u5165 src-tauri \u76ee\u5f55\ncd src-tauri\n\n# 2. \u5b89\u88c5 window-vibrancy\ncargo add window-vibrancy\n\u5b89\u88c5\u5b8c\u6210\u540e\u4f1a\u5728 Cargo.toml > dependencies \u4e2d\u770b\u5230\u8be5\u4f9d\u8d56\u3002\n\n\nStep 2\n\u5728 src-tauri/src \u4e0b\u65b0\u5efa setup.rs \u6587\u4ef6\uff1a\n\nuse tauri::{App, Manager};\nuse window_vibrancy::{self, NSVisualEffectMaterial};\n\n/// setup\npub fn init(app: &mut App) -> std::result::Result<(), Box<dyn std::error::Error>> {\n    let win = app.get_window("main").unwrap();\n\n    // \u4ec5\u5728 macOS \u4e0b\u6267\u884c\n    #[cfg(target_os = "macos")]\n    window_vibrancy::apply_vibrancy(&win, NSVisualEffectMaterial::FullScreenUI)\n        .expect("Unsupported platform! \'apply_vibrancy\' is only supported on macOS");\n\n    // \u4ec5\u5728 windows \u4e0b\u6267\u884c\n    #[cfg(target_os = "windows")]\n    window_vibrancy::apply_blur(&win, Some((18, 18, 18, 125)))\n        .expect("Unsupported platform! \'apply_blur\' is only supported on Windows");\n\n    Ok(())\n}\n\u4ee3\u7801\u4e2d\u7684 #[cfg(target_os)] \u662f\u6307\u6761\u4ef6\u7f16\u8bd1\uff0c\u4ec5\u5728\u76ee\u6807\u7684\u64cd\u4f5c\u7cfb\u7edf\u4e2d\u6267\u884c\u76f8\u5173\u4ee3\u7801\uff0c\u53ef\u4ee5\u67e5\u770b conditional compilation - target_os \u4e86\u89e3\u66f4\u591a\u3002\n\nStep 3\n\u5728 src-tauri/src/main.rs \u4e2d\u4f7f\u7528 setup.rs\uff1a\n\nmod setup;\n\nfn main() {\n    let context = tauri::generate_context!();\n    tauri::Builder::default()\n        .setup(setup::init)\n        .run(context)\n        .expect("error while running OhMyBox application");\n}\nsetup \u662f\u4e00\u4e2a Rust \u6a21\u5757\uff0c\u7b80\u5355\u6765\u8bb2\u5c31\u662f\u6309\u7167\u903b\u8f91\u5355\u5143\u6216\u529f\u80fd\u6a21\u5757\u8fdb\u884c\u4ee3\u7801\u62c6\u5206\u3002\u53ef\u4ee5\u67e5\u770b rust-by-example - mod \u4e86\u89e3\u66f4\u591a\u3002\n\n\n'})})]})}function d(n={}){const{wrapper:e}={...(0,i.R)(),...n.components};return e?(0,o.jsx)(e,{...n,children:(0,o.jsx)(u,{...n})}):u(n)}},28453(n,e,t){t.d(e,{R:()=>a,x:()=>s});var r=t(96540);const o={},i=r.createContext(o);function a(n){const e=r.useContext(i);return r.useMemo(function(){return"function"==typeof n?n(e):{...e,...n}},[e,n])}function s(n){let e;return e=n.disableParentContext?"function"==typeof n.components?n.components(o):n.components||o:a(n.components),r.createElement(i.Provider,{value:e},n.children)}}}]);